package com.kaipai.service.ai.profileimport;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import com.kaipai.common.exception.BizException; import com.kaipai.integration.ai.profileimport.DeepSeekProfileTextExtractor; import com.kaipai.model.ai.entity.AiProfileImportConfig; import org.junit.jupiter.api.Test;
class DeepSeekProfileTextExtractorTest { @Test void invalidResponseGetsOneRepairThenReturns46007(){var transport=mock(ProfileImportHttpTransport.class);when(transport.post(any(),any(),any())).thenReturn("not json","still not json");var extractor=new DeepSeekProfileTextExtractor(transport);var c=config();var e=assertThrows(BizException.class,()->extractor.extract(c,"sk-memory-only","演员王火火","req-1"));assertEquals(46007,e.getCode());verify(transport,times(2)).post(eq(c.getEndpoint()),eq("sk-memory-only"),any());} @Test void validResponseReturnsStructuredJson(){var transport=mock(ProfileImportHttpTransport.class);when(transport.post(any(),any(),any())).thenReturn("{\"profileCandidates\":[] ,\"workCandidates\":[]}");var result=new DeepSeekProfileTextExtractor(transport).extract(config(),"sk-memory-only","文本","req-1");assertEquals(0,result.path("profileCandidates").size());} @Test void timeoutMapsTo46006(){var transport=mock(ProfileImportHttpTransport.class);when(transport.post(any(),any(),any())).thenThrow(new ProfileImportHttpTransport.Timeout());var e=assertThrows(BizException.class,()->new DeepSeekProfileTextExtractor(transport).extract(config(),"sk","文本","req"));assertEquals(46006,e.getCode());} private AiProfileImportConfig config(){var c=new AiProfileImportConfig();c.setEndpoint("https://api.deepseek.com/chat/completions");c.setModelName("deepseek-chat");c.setReadTimeoutMs(1000);return c;}}
